static int vc_sm_cma_vchi_import(struct sm_instance *s,struct vc_sm_import *m,struct vc_sm_import_result *r,u32 *id,void (*done)(void *,u32),void *ctx){last_id=m->kernel_id;struct vc_sm_buffer *b=ctx;assert(b->in_use&&b->size==4096&&idr_find(&b->owner->kernelid_map,last_id)==b);if(import_status)return import_status;r->res_handle=reply_handle;if(early_event==2)event(b->owner,last_id,reply_handle,sizeof(struct vc_sm_released));done(ctx,reply_handle);if(early_event==1)event(b->owner,last_id,reply_handle,sizeof(struct vc_sm_released));return 0;}
